def call_first_agent(query: str) -> str:
    """
    A2A Protocol로 기본 에이전트를 호출합니다. OpenAI SDK 기반. 포트 9017.
    A2A Protocol (JSON-RPC 2.0) - Port 9017

    Args:
        query: 질문 또는 요청 텍스트

    Returns:
        에이전트 응답 텍스트
    """
    import requests, uuid, json
    message_id = str(uuid.uuid4())
    payload = {
        "jsonrpc": "2.0",
        "method": "message/send",
        "id": message_id,
        "params": {
            "message": {
                "messageId": message_id,
                "role": "user",
                "parts": [{"kind": "text", "text": query}]
            }
        }
    }
    try:
        resp = requests.post("http://127.0.0.1:9017/", json=payload, timeout=60)
        resp.raise_for_status()
        result = resp.json()
        if "result" in result:
            for artifact in result["result"].get("artifacts", []):
                for part in artifact.get("parts", []):
                    if part.get("kind") == "text" or part.get("type") == "text":
                        return part.get("text", "")
            parts = result["result"].get("parts", [])
            for part in parts:
                if part.get("kind") == "text" or part.get("type") == "text":
                    return part.get("text", "")
        return json.dumps(result, ensure_ascii=False)
    except requests.exceptions.ConnectionError:
        return f"[Error] A2A server not running at http://127.0.0.1:9017/. Start with: python a2a_server.py"
    except Exception as e:
        return f"[Error] {str(e)}"

